.auth-panel{
  position: relative;
  width: 100%;
  justify-self: end;
  padding: clamp(24px, 3vw, 30px);
  border-radius: var(--gc-radius-lg, 4px);
  background: linear-gradient(180deg, rgba(4, 9, 22, 0.96), rgba(2, 6, 16, 0.94));
  border: 1px solid rgba(70, 229, 255, 0.22);
