/* GC-BST — Buildings planet stage: clear planet landscape + round props + inline +1/MAX */
.bld-planet-stage{
  position: relative;
  margin: 0 0 12px;
  min-height: clamp(280px, 42vh, 460px);
  border: 1px solid rgba(var(--gc-id-rgb), 0.22);
  border-radius: var(--gc-radius-sm, 2px);
  overflow: hidden;
  background: transparent;
}
.bld-planet-stage-toolbar{
  position: absolute;
  top: 8px;
  left: 8px;
  right: 8px;
  z-index: 5;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  pointer-events: none;
}
.bld-planet-stage-toolbar .gc-btn,
.bld-stage-arrange-hint{
  pointer-events: auto;
}
.bld-stage-arrange-btn,
.bld-stage-reset-btn{
  min-height: 28px;
  padding: 2px 10px;
  font-size: 0.72rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  background: rgba(4, 10, 22, 0.82);
}
.bld-stage-arrange-btn[aria-pressed="true"]{
  border-color: rgba(255, 220, 90, 0.7);
  color: #ffe28a;
}
.bld-stage-arrange-hint{
  font-size: 0.72rem;
  color: var(--gc-text-soft, #9bb4c8);
  background: rgba(4, 10, 22, 0.75);
  border: 1px solid rgba(70, 229, 255, 0.18);
  padding: 4px 8px;
}
.bld-planet-stage--arrange{
  outline: 1px dashed rgba(255, 220, 90, 0.45);
  outline-offset: -2px;
}
.bld-planet-stage--arrange .bld-planet-stage-surface{
  filter: none;
}
.bld-planet-stage--arrange .bld-planet-stage-props{
  background-image:
    linear-gradient(rgba(255, 220, 90, 0.07) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 220, 90, 0.07) 1px, transparent 1px);
  background-size: 10% 10%;
}
.bld-planet-stage-surface{
  position: absolute;
  inset: 0;
  z-index: 0;
  background-color: #040810;
  /* Landscape must stay sharp and readable — no blur, light read-scrim only */
  background-image:
    linear-gradient(180deg, rgba(2, 6, 14, 0.18) 0%, transparent 32%, rgba(2, 6, 14, 0.28) 100%),
    var(--planet-landscape, none);
  background-size: cover;
  background-position: center center;
  background-repeat: no-repeat;
  filter: none;
  pointer-events: none;
}
@supports (background-image: image-set(url("x") type("image/webp"))) {
  .bld-planet-stage-surface{
    background-image:
      linear-gradient(180deg, rgba(2, 6, 14, 0.18) 0%, transparent 32%, rgba(2, 6, 14, 0.28) 100%),
      image-set(
        var(--planet-landscape-webp, var(--planet-landscape, none)) type("image/webp"),
        var(--planet-landscape, none) type("image/png")
      );
  }
}
.bld-planet-stage--resync .bld-planet-stage-props{
  opacity: 0.35;
  transition: opacity 0.12s ease;
}
.bld-planet-stage-shade{
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  /* Soft edge vignette only — do not crush the landscape */
  background:
    radial-gradient(ellipse 95% 85% at 50% 45%, transparent 55%, rgba(2, 6, 14, 0.28) 100%);
}
.bld-planet-stage-props{
  position: absolute;
  inset: 0;
  z-index: 3;
}
.bld-stage-prop{
  position: absolute;
  transform: translate(-50%, -70%) scale(var(--bld-stage-scale, 1));
  width: 72px;
  height: 72px;
  padding: 0;
  margin: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  cursor: pointer;
  color: inherit;
  box-shadow: none;
  transition: filter 0.15s ease, transform 0.12s ease;
  touch-action: none;
  --bld-stage-progress: 0;
}
.bld-stage-prop.is-stage-tab-hidden,
.bld-stage-prop[hidden]{
  display: none !important;
}
.bld-stage-prop-halo{
  position: absolute;
  left: 50%;
  bottom: 2%;
  width: 72%;
  height: 18%;
  transform: translateX(-50%);
  border-radius: 50%;
  background: radial-gradient(ellipse at center, rgba(0,0,0,0.72) 0%, transparent 72%);
  pointer-events: none;
  z-index: 0;
}
.bld-planet-stage--arrange .bld-stage-prop,
.bld-stage-prop.is-dragging{
  transition: none !important;
}
.bld-planet-stage--arrange .bld-stage-prop{
  cursor: grab;
}
.bld-stage-prop.is-dragging{
  cursor: grabbing;
  z-index: 30 !important;
  transform: translate(-50%, -70%) scale(var(--bld-stage-scale, 1));
}
.bld-stage-prop:hover,
.bld-stage-prop:focus-visible{
  outline: none;
  z-index: 20 !important;
  filter: brightness(1.12);
}
.bld-planet-stage--arrange .bld-stage-prop:hover,
.bld-planet-stage--arrange .bld-stage-prop:focus-visible{
  filter: none;
  transform: translate(-50%, -70%) scale(var(--bld-stage-scale, 1));
}
.bld-stage-prop-art{
  position: relative;
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;
  z-index: 1;
  border-radius: 50%;
  border: 1px solid rgba(var(--gc-id-rgb), 0.48);
  background: rgba(4, 10, 22, 0.35);
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, 0.45),
    0 0 12px rgba(var(--gc-id-rgb), 0.22);
}
.bld-stage-prop-art img{
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 40%;
  filter:
    drop-shadow(0 2px 3px rgba(0, 0, 0, 0.75))
    saturate(1.05);
}
.bld-stage-prop-level{
  position: absolute;
  right: -2px;
  bottom: 4%;
  z-index: 3;
  min-width: 1.45em;
  padding: 1px 4px;
  font-size: 0.68rem;
  line-height: 1.2;
  text-align: center;
  color: #e8f7ff;
  background: rgba(2, 6, 14, 0.92);
  border: 1px solid rgba(var(--gc-id-rgb), 0.5);
  border-radius: var(--gc-radius-sm, 2px);
  box-shadow: 0 0 8px rgba(var(--gc-id-rgb), 0.22);
  pointer-events: none;
}
.bld-stage-prop-actions{
  position: absolute;
  left: 50%;
  top: calc(100% + 4px);
  transform: translateX(-50%);
  z-index: 4;
  margin: 0;
  padding: 0;
  width: max-content;
  max-width: 118px;
}
.bld-stage-prop-actions .gc-bld-card-head-action-group{
  transform: scale(0.72);
  transform-origin: top center;
  border-color: rgba(var(--gc-id-rgb), 0.55);
  background: rgba(6, 12, 20, 0.92);
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, 0.28) inset,
    0 0 14px rgba(var(--gc-id-rgb), 0.2);
}
.bld-stage-prop-actions .gc-bld-card-head-action-group .gc-bld-head-action-btn--plus-one{
  border-right-color: rgba(var(--gc-id-rgb), 0.3);
}
.bld-stage-prop-actions a.gc-bld-head-action-btn--go,
.bld-stage-prop-actions button.gc-bld-head-action-btn--go{
  border-color: rgba(var(--gc-id-rgb), 0.78);
  background: linear-gradient(
    180deg,
    rgba(var(--gc-id-rgb), 0.48) 0%,
    rgba(var(--gc-id-rgb), 0.22) 100%
  );
  color: #fff8e8;
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, 0.32) inset,
    0 0 14px rgba(var(--gc-id-rgb), 0.32);
}
.bld-stage-prop-actions a.gc-bld-head-action-btn--go:hover,
.bld-stage-prop-actions a.gc-bld-head-action-btn--go:focus-visible{
  border-color: rgba(var(--gc-id-rgb), 0.95);
  background: linear-gradient(
    180deg,
    rgba(var(--gc-id-rgb), 0.62) 0%,
    rgba(var(--gc-id-rgb), 0.34) 100%
  );
  color: #ffffff;
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, 0.32) inset,
    0 0 20px rgba(var(--gc-id-rgb), 0.45);
}
.bld-stage-prop-actions .gc-bld-head-action-btn--queue-max{
  border-color: rgba(var(--gc-id-rgb), 0.45);
  color: color-mix(in srgb, rgb(var(--gc-id-rgb)) 70%, #ffffff);
  background: linear-gradient(
    180deg,
    rgba(var(--gc-id-rgb), 0.18) 0%,
    rgba(8, 12, 20, 0.96) 100%
  );
}
.bld-stage-prop-actions .gc-bld-head-action-btn--queue-max:not(:disabled):hover,
.bld-stage-prop-actions .gc-bld-head-action-btn--queue-max:not(:disabled):focus-visible{
  border-color: rgba(var(--gc-id-rgb), 0.85);
  color: #ffffff;
  background: linear-gradient(
    180deg,
    rgba(var(--gc-id-rgb), 0.32) 0%,
    rgba(10, 14, 22, 0.98) 100%
  );
  box-shadow: 0 0 16px rgba(var(--gc-id-rgb), 0.32);
}
.bld-stage-prop-actions .gc-bld-head-action-btn--warn{
  border-color: rgba(251, 191, 36, 0.55);
  color: rgba(255, 220, 140, 0.96);
}
.bld-stage-prop-actions .gc-bld-head-action-btn--max{
  border-color: rgba(var(--gc-id-rgb), 0.4);
  color: color-mix(in srgb, rgb(var(--gc-id-rgb)) 55%, #ffffff);
}
.bld-stage-prop-actions .gc-bld-head-action-btn:not(.gc-bld-head-action-btn--plus-one):not(.gc-bld-head-action-btn--queue-max){
  min-width: 28px;
  min-height: 28px;
}
.bld-planet-stage--arrange .bld-stage-prop-actions{
  pointer-events: none;
  opacity: 0.28;
}
.bld-stage-prop-build{
  position: absolute;
  inset: -7px;
  z-index: 2;
  pointer-events: none;
  border-radius: 50%;
  opacity: 0;
  background:
    conic-gradient(
      from -90deg,
      rgba(127, 255, 217, 0.98) calc(var(--bld-stage-progress) * 1%),
      rgba(70, 229, 255, 0.18) 0
    );
  -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 5px), #000 calc(100% - 3.5px));
  mask: radial-gradient(farthest-side, transparent calc(100% - 5px), #000 calc(100% - 3.5px));
  box-shadow: 0 0 14px rgba(127, 255, 217, 0.35);
}
.bld-stage-prop--locked{
  opacity: 0.48;
  filter: grayscale(0.45) brightness(0.85);
}
.bld-stage-prop--warn .bld-stage-prop-art{
  border-color: rgba(255, 180, 70, 0.65);
  box-shadow: 0 0 12px rgba(255, 180, 70, 0.28);
}
.bld-stage-prop--queue .bld-stage-prop-build{
  opacity: 1;
  animation: bld-stage-build-pulse 1.2s ease-in-out infinite;
}
.bld-stage-prop--queue .bld-stage-prop-art{
  border-color: rgba(127, 255, 217, 0.88);
  box-shadow:
    0 0 0 1px rgba(127, 255, 217, 0.35),
    0 0 18px rgba(127, 255, 217, 0.55),
    0 0 28px rgba(70, 229, 255, 0.28);
  animation: bld-stage-art-pulse 1.4s ease-in-out infinite;
}
.bld-stage-prop--queue::before{
  content: "";
  position: absolute;
  left: 10%;
  right: 10%;
  top: 8%;
  height: 4px;
  z-index: 2;
  pointer-events: none;
  border-radius: 50%;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(127, 255, 217, 0.2) 18%,
    rgba(255, 255, 255, 0.95) 50%,
    rgba(127, 255, 217, 0.2) 82%,
    transparent
  );
  background-size: 220% 100%;
  animation: bld-stage-scan 1.25s linear infinite;
  box-shadow: 0 0 12px rgba(127, 255, 217, 0.65);
}
.bld-stage-prop--max .bld-stage-prop-level{
  border-color: rgba(180, 190, 210, 0.55);
  color: #d0d6e0;
}
.bld-stage-prop.is-focused{
  z-index: 22 !important;
}
.bld-stage-prop.is-focused .bld-stage-prop-art{
  border-color: rgba(255, 220, 90, 0.9);
  box-shadow: 0 0 16px rgba(255, 220, 90, 0.45);
}
@keyframes bld-stage-build-pulse{
  0%, 100%{ filter: brightness(1); opacity: 0.85; }
  50%{ filter: brightness(1.35); opacity: 1; }
}
@keyframes bld-stage-art-pulse{
  0%, 100%{ filter: brightness(1) saturate(1.05); }
  50%{ filter: brightness(1.22) saturate(1.2); }
}
@keyframes bld-stage-scan{
  0%{ background-position: 100% 0; transform: translateY(0); opacity: 0.4; }
  50%{ opacity: 1; }
  100%{ background-position: -100% 0; transform: translateY(54px); opacity: 0.4; }
}
