  flex: 0 0 var(--gc-queue-card-slot-w, 248px);
  width: var(--gc-queue-card-slot-w, 248px);
  min-width: var(--gc-queue-card-slot-w, 248px);
  max-width: var(--gc-queue-card-slot-w, 248px);
