}

@keyframes gc-card-queue-orbit-pulse{
  0%, 100%{
    opacity: 0.55;
    box-shadow: 0 0 0 rgba(170, 150, 255, 0);
    transform: rotate(0deg);
  }
  50%{
    opacity: 1;
