}

@keyframes gc-card-queue-core-ripple{
  0%{ transform: scale(0.85); opacity: 0.35; }
  70%{ transform: scale(1.15); opacity: 0.75; }
  100%{ transform: scale(1.2); opacity: 0; }
}

