  background: rgba(255,255,255,0.03);
  box-shadow: 0 0 0 1px rgba(255,255,255,0.06) inset;
}

.gc-cost-val{
  font-family: var(--gc-mono);
  font-variant-numeric: tabular-nums;
  font-weight: 900;
  white-space: nowrap;
