/* ==========================================================================
   GC Page Tabs — canonical tab rail (Records look, Identity Shell reactive)
   Active accent follows equipped PlayerCard theme via --gc-neon-cyan /
   --gc-id-rgb (body[data-identity-theme]). See docs/PAYMENT_SHOP.md.
   ========================================================================== */
.gc-page-tabs{
  display: grid;
  grid-template-columns: repeat(var(--gc-page-tabs-cols, 4), minmax(0, 1fr));
  gap: 0;
  margin: 0 0 12px;
  border-bottom: 1px solid color-mix(in srgb, var(--gc-neon-cyan) 28%, transparent);
  background:
    linear-gradient(180deg, rgba(10, 18, 36, 0.98) 0%, rgba(4, 10, 22, 0.96) 100%);
  box-shadow: inset 0 -1px 0 rgba(0, 0, 0, 0.45);
  position: relative;
  z-index: 1;
  max-width: 100%;
  min-width: 0;
}

.gc-page-tabs--cols-2{ --gc-page-tabs-cols: 2; }
.gc-page-tabs--cols-3{ --gc-page-tabs-cols: 3; }
.gc-page-tabs--cols-4{ --gc-page-tabs-cols: 4; }
.gc-page-tabs--cols-5{ --gc-page-tabs-cols: 5; }
.gc-page-tabs--cols-6{ --gc-page-tabs-cols: 6; }
.gc-page-tabs--cols-7{ --gc-page-tabs-cols: 7; }

.gc-page-tabs--auto{
  display: flex;
  flex-wrap: wrap;
}
.gc-page-tabs--auto > .gc-page-tab{
  flex: 1 1 7rem;
}

.gc-page-tabs--inline{
  margin: 0;
  flex-shrink: 0;
}

.gc-page-tabs--sm .gc-page-tab{
  min-height: 36px;
  padding: 8px 6px;
  font-size: 0.62rem;
}

.gc-page-tab{
  appearance: none;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-width: 0;
  min-height: 48px;
  margin: 0;
  padding: 12px 8px;
  border: none;
  border-right: 1px solid color-mix(in srgb, var(--gc-neon-cyan) 12%, transparent);
  border-radius: 0;
  background: transparent;
  color: var(--gc-text-dim);
  font-family: Orbitron, Inter, system-ui, sans-serif;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-decoration: none;
  cursor: pointer;
  transition: color 0.15s ease, background 0.15s ease;
  box-shadow: none;
  text-shadow: none;
  white-space: nowrap;
}

.gc-page-tabs > .gc-page-tab:last-child,
.gc-page-tabs > a.gc-page-tab:last-child{
  border-right: none;
}

.gc-page-tab-label{
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  line-height: 1.2;
}

.gc-page-tab:hover{
  color: var(--gc-text-soft);
  background: color-mix(in srgb, var(--gc-neon-cyan) 5%, transparent);
  text-decoration: none;
}

.gc-page-tab:focus-visible{
  outline: none;
  color: var(--gc-neon-cyan);
  background: color-mix(in srgb, var(--gc-neon-cyan) 8%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--gc-neon-cyan) 35%, transparent);
}

.gc-page-tab.is-active,
.gc-page-tab.active,
.gc-page-tab.gp-tab--active,
.gc-page-tab[aria-selected="true"],
.gc-page-tab[aria-current="page"]{
  color: var(--gc-neon-cyan);
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--gc-neon-cyan) 14%, transparent) 0%,
      color-mix(in srgb, var(--gc-neon-cyan) 4%, transparent) 100%
    );
  box-shadow: inset 0 -3px 0 var(--gc-neon-cyan);
  text-shadow: 0 0 12px color-mix(in srgb, var(--gc-neon-cyan) 35%, transparent);
  border-color: transparent;
  text-decoration: none;
}

a.gc-page-tab.gc-nav-link{
  border-left: none;
  box-shadow: none;
}

a.gc-page-tab.gc-nav-link.is-active,
a.gc-page-tab.gc-nav-link.active,
a.gc-page-tab.gc-nav-link[aria-current="page"]{
  box-shadow: inset 0 -3px 0 var(--gc-neon-cyan);
}

.gc-page-tab--rich{
  flex-direction: column;
  align-items: stretch;
  gap: 2px;
  white-space: normal;
  text-align: left;
  padding: 8px 10px;
  min-height: 56px;
}

/* Reset legacy button chrome when migrated onto the page-tab rail */
.gc-page-tab.gc-btn,
.gc-page-tab.gc-btn-ghost,
.gc-page-tab.gc-btn-outline,
.gc-page-tab.gc-btn-sm,
.gc-page-tab.tab-btn{
  border: none;
  border-right: 1px solid color-mix(in srgb, var(--gc-neon-cyan) 12%, transparent);
  border-radius: 0;
  box-shadow: none;
  background: transparent;
  min-height: 48px;
  padding: 12px 8px;
  font-family: Orbitron, Inter, system-ui, sans-serif;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--gc-text-dim);
}
.gc-page-tabs > .gc-page-tab.gc-btn:last-child,
.gc-page-tabs > .gc-page-tab.tab-btn:last-child{
  border-right: none;
}
.gc-page-tab.tab-btn.active,
.gc-page-tab.gc-btn.active,
.gc-page-tab.gc-btn.is-active{
  color: var(--gc-neon-cyan);
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--gc-neon-cyan) 14%, transparent) 0%,
      color-mix(in srgb, var(--gc-neon-cyan) 4%, transparent) 100%
    );
  box-shadow: inset 0 -3px 0 var(--gc-neon-cyan);
  border-color: transparent;
  text-shadow: 0 0 12px color-mix(in srgb, var(--gc-neon-cyan) 35%, transparent);
}

@media (max-width: 720px){
  .gc-page-tabs--cols-5,
  .gc-page-tabs--cols-6,
  .gc-page-tabs--cols-7{
    --gc-page-tabs-cols: 3;
  }
  .gc-page-tabs--cols-5 > .gc-page-tab:nth-child(3n),
  .gc-page-tabs--cols-6 > .gc-page-tab:nth-child(3n),
  .gc-page-tabs--cols-7 > .gc-page-tab:nth-child(3n){
    border-right: none;
  }
  .gc-page-tabs--cols-5 > .gc-page-tab:nth-child(n+4),
  .gc-page-tabs--cols-6 > .gc-page-tab:nth-child(n+4),
  .gc-page-tabs--cols-7 > .gc-page-tab:nth-child(n+4){
    border-top: 1px solid color-mix(in srgb, var(--gc-neon-cyan) 12%, transparent);
