}

.gc-codex-locked-label{
  font-size: 0.68rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--gc-text-soft);
}

.gc-codex-teaser{
  margin: 6px 0 0;
  font-size: 0.78rem;
}

.gc-codex-article-read{
  font-size: 0.68rem;
  color: var(--gc-text-soft);
}

.gc-codex-article-view{
  margin-top: 8px;
}

.gc-codex-article-view:not(.is-open){
