  opacity: 0.92;
}

.gc-codex-empty{
  margin: 0;
  font-size: 0.82rem;
}

.gc-codex-unlock-label{
  margin: 8px 0 0;
  font-size: 0.78rem;
}

.gc-codex-article-heading{
  margin: 0 0 10px;
  font-size: 1rem;
  color: var(--gc-primary);
}

.gc-codex-section{
  margin-bottom: 12px;
}

.gc-codex-section-title{
  margin: 0 0 6px;
  font-size: 0.72rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--gc-text-soft);
}

.gc-codex-faq dt{
  font-weight: 700;
  margin-top: 8px;
}

.gc-codex-faq dd{
  margin: 4px 0 0;
  color: var(--gc-text-soft);
}

.gc-codex-related{
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.gc-codex-context-btn{
  min-width: 28px;
  min-height: 28px;
  padding: 0 8px;
  font-weight: 800;
  line-height: 1;
}

.gc-codex-commander-tip-mobile .gc-codex-commander-tip{
  margin-bottom: 10px;
}

.gc-codex-commander-tip-mobile .gc-codex-commander-tip-head{
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 6px;
}

.gc-codex-commander-tip-mobile .gc-codex-commander-tip-label{
  font-size: 0.72rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  font-weight: 800;
  color: var(--gc-primary);
}

.gc-codex-commander-tip-mobile .gc-codex-commander-tip-badge{
  font-size: 0.62rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #ffb347;
}

.gc-codex-commander-tip-mobile .gc-codex-commander-tip-text{
  margin: 0 0 8px;
  font-size: 0.8rem;
}

.gc-codex-commander-tip-mobile{
  display: none !important;
}

.gc-special-head{
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 10px;
}

.gc-special-head .gc-btn{
  border-radius: 0;
}

.gc-special-title{
  font-family: Orbitron, Inter, system-ui, sans-serif;
  color: var(--gc-primary);
  font-size: 0.95rem;
  letter-spacing: 0.05em;
  font-weight: 800;
  text-transform: uppercase;
}

.gc-special-window-layout{
  display: grid;
  grid-template-columns: 132px 1fr;
  gap: 10px;
}

.gc-special-window-nav{
  display: grid;
  gap: 6px;
}

.gc-special-window-nav-btn{
  min-height: 32px;
  border-radius: 0;
  border: 1px solid rgba(120, 190, 255, 0.22);
  background: rgba(9, 18, 36, 0.92);
  color: var(--gc-text-soft);
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  cursor: pointer;
}

.gc-special-window-content h3{
  margin: 0 0 8px;
  font-size: 1rem;
}

.gc-special-intro{
  margin: 0 0 10px;
  color: var(--gc-text-soft);
  font-size: 0.9rem;
}

.gc-special-card{
  margin: 0 0 8px;
  border-radius: 0;
  border: 1px solid rgba(120, 190, 255, 0.17);
  background: rgba(7, 15, 31, 0.82);
  padding: 8px 10px;
}

.gc-special-card summary{
  cursor: pointer;
  font-weight: 700;
  color: var(--gc-primary-2);
}

.gc-special-card p{
  margin: 8px 0 0;
  color: var(--gc-text-soft);
  font-size: 0.88rem;
  line-height: 1.42;
}

.gc-rules-panel-body{
  margin-top: 8px;
  color: var(--gc-text-soft);
  font-size: 0.88rem;
  line-height: 1.45;
}

.gc-rules-panel-body p{
  margin: 0 0 8px;
}

.gc-rules-panel-body p:last-child{
  margin-bottom: 0;
}

.gc-rules-panel-body strong{
  color: var(--gc-text);
}

.gc-rules-panel-faq{
  margin-top: 14px;
  padding-top: 10px;
  border-top: 1px solid rgba(120, 190, 255, 0.12);
}

.gc-rules-panel-faq-title{
  margin: 0 0 8px;
  font-size: 0.95rem;
  color: var(--gc-primary-2);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.gc-rules-panel-faq-item summary{
  font-size: 0.88rem;
  font-weight: 600;
}

.gc-rules-panel-footer{
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 14px;
  padding-top: 10px;
  border-top: 1px solid rgba(120, 190, 255, 0.12);
}

.gc-rules-panel-version{
  margin: 0;
  font-size: 0.75rem;
  color: var(--gc-text-muted, var(--gc-text-soft));
  opacity: 0.85;
}

/* Legal panel (imprint special window + public /legal) */
.gc-legal-panel{
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.gc-legal-provider-lines,
.legal-provider-lines{
  margin: 0 0 8px;
  line-height: 1.45;
  font-size: 0.88rem;
}
/* legal tabs: visual owned by .gc-page-tabs */
.gc-legal-tabs,
.legal-doc-tabs{ margin: 0 0 8px; }

.gc-legal-doc-title{
  margin: 0 0 8px;
  font-size: 0.95rem;
}
.gc-legal-footer{
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid rgba(120, 190, 255, 0.14);
}
.gc-legal-footer-actions{
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.gc-legal-stand,
.legal-stand{
  margin: 8px 0 0;
  font-size: 0.75rem;
  color: var(--gc-text-soft);
}
.gc-legal-ack{
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0 0 10px;
  padding: 8px 10px;
  border: 1px solid rgba(120, 190, 255, 0.2);
  background: rgba(7, 15, 31, 0.75);
  border-radius: var(--gc-radius-sm, 2px);
}
.gc-legal-ack-row{
  display: flex;
  gap: 8px;
  align-items: flex-start;
  font-size: 0.82rem;
  color: var(--gc-text-soft);
  line-height: 1.4;
  cursor: pointer;
}
.gc-legal-ack-row input{
  margin-top: 3px;
  flex: 0 0 auto;
}
.gc-legal-ack-link{
  appearance: none;
  border: 0;
  background: none;
  color: var(--gc-primary-2);
  padding: 0;
  font: inherit;
  text-decoration: underline;
  cursor: pointer;
}
.auth-legal-footer,
.auth-legal-links{
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: center;
  align-items: center;
  margin-top: 12px;
  font-size: 0.78rem;
  color: var(--gc-text-soft);
}
.auth-legal-footer a,
.auth-legal-links a{
  color: var(--gc-text-soft);
  text-decoration: underline;
}
.auth-legal-footer a:hover,
.auth-legal-links a:hover{
  color: var(--gc-primary-2);
}
.shop-legal-footer{
  margin-bottom: 8px;
}
.legal-page .legal-doc-panel{
  margin-top: 10px;
}

.gc-cookie-notice{
  position: fixed;
  left: 12px;
  right: 12px;
  bottom: 12px;
  z-index: var(--gc-z-popover, 1200);
  max-width: 420px;
  margin: 0 auto;
  pointer-events: none;
}
.gc-cookie-notice:not([hidden]){
  pointer-events: auto;
}
.gc-cookie-notice-inner{
  border: 1px solid rgba(120, 190, 255, 0.28);
  background: rgba(6, 12, 24, 0.96);
  padding: 12px 14px;
  border-radius: var(--gc-radius-sm, 2px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.45);
}
.gc-cookie-notice-title{
  margin: 0 0 6px;
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--gc-primary-2);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.gc-cookie-notice-body{
  margin: 0 0 10px;
  font-size: 0.82rem;
  line-height: 1.4;
  color: var(--gc-text-soft);
}
.gc-cookie-notice-actions{
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: flex-end;
}
.auth-check--legal{
  display: flex;
  gap: 8px;
  align-items: flex-start;
  margin: 0 0 8px;
  font-size: 0.82rem;
  color: var(--gc-text-soft);
  line-height: 1.4;
  cursor: pointer;
}
.auth-check--legal input{
  margin-top: 3px;
  flex: 0 0 auto;
}
.auth-legal-acks{
  margin: 0 0 12px;
}


.gc-support-form{
  display: grid;
  gap: 8px;
  margin-bottom: 12px;
}

.gc-support-grid{
  display: grid;
  grid-template-columns: 1fr 140px 120px;
  gap: 8px;
}

.gc-support-field{
  display: grid;
  gap: 4px;
  font-size: 0.78rem;
  color: var(--gc-text-soft);
}

.gc-support-field input,
.gc-support-field select,
.gc-support-field textarea,
.gc-support-reply{
  width: 100%;
  border-radius: 0;
  border: 1px solid rgba(120, 190, 255, 0.22);
  background: rgba(6, 12, 24, 0.9);
  color: var(--gc-text);
  padding: 8px;
  font: inherit;
}

.gc-support-feedback{
  font-size: 0.78rem;
  color: var(--gc-text-soft);
}

.gc-support-feedback.is-ok{ color: #6fffd8; }
.gc-support-feedback.is-error{ color: #ff8e8e; }

.gc-support-list-head{
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}

.gc-support-list{
  display: grid;
  gap: 8px;
}

.gc-support-empty{
  padding: 10px;
  border: 1px solid rgba(120, 190, 255, 0.16);
  background: rgba(7, 14, 29, 0.76);
  color: var(--gc-text-soft);
  font-size: 0.86rem;
}

.gc-support-ticket{
  border: 1px solid rgba(120, 190, 255, 0.2);
  background: rgba(7, 14, 29, 0.8);
  padding: 8px;
}

.gc-support-ticket > summary{
  cursor: pointer;
  display: grid;
  gap: 2px;
  list-style: none;
}

.gc-support-ticket-subject{
  color: var(--gc-primary);
  font-weight: 800;
}

.gc-support-ticket-meta{
  color: var(--gc-text-soft);
  font-size: 0.76rem;
}

.gc-support-ticket-body{
  margin-top: 8px;
  display: grid;
  gap: 8px;
}

.gc-support-timeline{
  display: grid;
  gap: 6px;
}

.gc-support-msg{
  border: 1px solid rgba(120, 190, 255, 0.14);
  background: rgba(5, 11, 22, 0.9);
  padding: 6px 8px;
}

.gc-support-msg-meta{
  font-size: 0.72rem;
  color: var(--gc-text-dim);
  margin-bottom: 4px;
}

.gc-support-msg-body{
  color: var(--gc-text-soft);
  white-space: pre-wrap;
}

.gc-support-ticket-controls{
  display: grid;
  gap: 6px;
}

/* Desktop: TCHAT launcher lives in .gc-special-bar; mobile uses floating FAB (chat.css) */
@media (min-width: 769px){
  .gc-chat-fab{
    display: none !important;
  }
}

@media (max-width: 768px){
  :root{
    --gc-header-h: auto;
    --gc-page-pad-y: 14px;
  }

  .gc-body-ingame{
    padding-bottom: calc(var(--gc-bottom-nav-h) + var(--gc-safe-bottom) + 12px);
  }

  /* Hide desktop sidebar; use bottom nav */
  .gc-sidebar-desktop{ display: none !important; }

  .gc-layout{
    padding-left: 12px;
    padding-right: 12px;
    padding-bottom: 8px;
  }

  /* Header: brand/HUD scroll; resource bar sticks below notch */
  .gc-header{
    position: relative;
    top: auto;
    padding-top: var(--gc-safe-top);
  }

  .gc-header-inner{ padding: 10px 12px; }

  .gc-header-grid{
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 8px;
  }

  .gc-hslot-brand{
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    min-width: 0;
  }

  .gc-hslot-res{
    display: flex !important;
    justify-content: stretch;
    width: 100%;
    min-width: 0;
    order: 2;
  }

  .gc-resource-sticky{
    position: sticky;
    top: var(--gc-safe-top);
    z-index: 52;
    width: 100%;
    padding-bottom: 4px;
    background:
      linear-gradient(180deg, rgba(6, 12, 22, 0.94) 0%, rgba(6, 12, 22, 0.88) 72%, transparent 100%);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
  }

  .gc-resource-sticky.is-scrolled{
    box-shadow: 0 10px 28px rgba(0, 0, 0, 0.42);
  }

  .gc-hslot-brand{ order: 1; }
  .gc-hslot-hud{ order: 3; }

  .resource-bar{
    max-width: none;
    width: 100%;
    justify-content: flex-start;
    flex-wrap: nowrap;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    gap: 6px;
    padding: 6px 8px;
    scrollbar-width: thin;
  }

  .res-block{ flex: 0 0 auto; }

  .gc-hslot-hud{
    flex-direction: column;
    align-items: stretch;
    gap: 8px;
    white-space: normal;
  }

  .gc-hud-cluster{
    flex-wrap: wrap;
    justify-content: flex-start;
    gap: 6px;
    white-space: normal;
  }

  .gc-header-pill{
    font-size: 0.76rem;
    padding: 6px 9px;
    max-width: 100%;
  }

  .gc-hud-user{
    flex-wrap: wrap;
    justify-content: space-between;
    gap: 8px;
  }

  .gc-user-info{
    flex: 1 1 auto;
    min-width: 0;
    max-width: calc(100% - 110px);
  }

  .gc-user-name{
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    display: block;
    max-width: 100%;
  }

  .logout-btn{
    min-height: var(--gc-touch-min);
    min-width: var(--gc-touch-min);
    padding: 10px 14px !important;
  }

  .gc-title{
    font-size: 0.82rem;
    display: inline;
  }

  /* Cards & panels ? mehr vertikaler Abstand */
  .gc-panel{ padding: 14px; margin-bottom: 4px; }
  .gc-panel + .gc-panel{ margin-top: 2px; }

  .gc-grid-2,
  .research-grid,
  .gc-ranking-body{
    gap: clamp(16px, 4vw, 22px);
  }

  .gc-flash-container{ gap: 10px; margin-bottom: 14px; }

  .research-list{ gap: var(--gc-card-gap); }
  .research-item,
  .overview-res-card,
  .galaxy-system-card,
  .ranking-stat{
    margin-bottom: 2px;
  }

  .overview-resources{
    grid-template-columns: 1fr;
    gap: clamp(14px, 3.5vw, 18px);
  }

  .overview-res-card{ padding: 16px; }

  .gc-panel-header{
    flex-direction: column;
    align-items: flex-start;
  }

  .building-tabs{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
  }

  .building-tabs .tab-btn,
  .building-tabs .gc-btn{
    min-height: var(--gc-touch-min);
    width: 100%;
  }

  .gc-btn,
  .gc-btn-sm,
  a.gc-btn{
    min-height: var(--gc-touch-min);
  }

  .btn-upgrade:not(.gc-bld-head-action-btn),
  .btn-research:not(.gc-bld-head-action-btn){
    min-width: var(--gc-touch-min);
    padding: 10px 14px !important;
  }

  .active-build-wrapper,
  .active-research-wrapper{
    grid-template-columns: 1fr;
  }

  .build-icon-large,
  .research-icon-large{
    width: 72px;
    height: 72px;
    margin: 0 auto;
  }

  .section-header{ padding: 12px; margin-bottom: 12px; }

  .motd-banner{
    flex-direction: row;
    align-items: flex-start;
  }
  .motd-banner--expanded .motd-banner-toggle{
    flex-direction: column;
    align-items: flex-start;
  }

  /* Bottom navigation */
  .gc-bottom-nav{
    display: flex;
    position: fixed;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 60;
    min-height: calc(var(--gc-bottom-nav-h) + var(--gc-safe-bottom));
    padding:
      6px
      max(6px, var(--gc-safe-left))
      calc(6px + var(--gc-safe-bottom))
      max(6px, var(--gc-safe-right));
    gap: 4px;
    background: linear-gradient(180deg, rgba(6,12,22,0.82), rgba(4,8,18,0.98));
    border-top: 1px solid var(--gc-hdr-border);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    box-shadow: 0 -12px 40px rgba(0,0,0,0.55);
  }

  .gc-bottom-nav-item{
    position: relative;
    flex: 1 1 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 3px;
    min-height: var(--gc-touch-min);
    padding: 5px 3px;
    border: none;
    border-radius: var(--gc-radius-sm);
    background: transparent;
    color: var(--gc-text-dim);
    font: inherit;
    cursor: pointer;
    text-decoration: none;
    -webkit-tap-highlight-color: transparent;
    transition: color 0.16s ease, background 0.16s ease, transform 0.12s ease;
  }

  .gc-bottom-nav-item:active{
    transform: scale(0.96);
  }

  .gc-bottom-nav-item.active{
    color: var(--gc-primary-2);
    background: rgba(70, 229, 255, 0.10);
    box-shadow: 0 0 0 1px rgba(70, 229, 255, 0.24) inset;
  }

  .gc-bottom-nav-item.active::before{
    content: "";
    position: absolute;
    top: 2px;
    width: 22px;
    height: 3px;
    border-radius: var(--gc-radius-sm);
    background: var(--gc-primary);
    box-shadow: 0 0 12px rgba(70, 229, 255, 0.45);
  }

  .gc-bottom-nav-icon{ font-size: clamp(1.05rem, 4vw, 1.2rem); line-height: 1; }
  .gc-bottom-nav-label{
    font-size: var(--gc-font-nav);
    font-weight: 700;
    letter-spacing: 0.02em;
    text-align: center;
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .gc-bottom-nav-more.active{
    color: var(--gc-primary);
  }

  .gc-bottom-buildings-menu{
    position: fixed;
    left: max(8px, var(--gc-safe-left));
    right: max(8px, var(--gc-safe-right));
    bottom: calc(var(--gc-bottom-nav-h, 64px) + var(--gc-safe-bottom, 0px) + 8px);
    z-index: calc(var(--gc-z-dropdown, 12000) + 2);
    display: flex;
    flex-direction: column;
    gap: 4px;
    padding: 8px;
    border: 1px solid rgba(120, 190, 255, 0.28);
    border-radius: var(--gc-radius-sm, 2px);
    background: linear-gradient(180deg, rgba(8, 14, 28, 0.98), rgba(4, 8, 18, 0.96));
    box-shadow:
      0 0 0 1px rgba(0, 0, 0, 0.35) inset,
      0 14px 32px rgba(0, 0, 0, 0.55);
    opacity: 0;
    transform: translateY(8px);
    pointer-events: none;
    transition: opacity 0.16s ease, transform 0.16s ease;
  }

  .gc-bottom-buildings-menu[hidden]{
    display: none !important;
  }

  .gc-bottom-buildings-menu.is-open{
    opacity: 1;
    transform: translateY(0);
    pointer-events: auto;
  }

  .gc-bottom-buildings-menu-item{
    display: block;
    width: 100%;
    margin: 0;
    padding: 10px 12px;
    border: 1px solid rgba(120, 190, 255, 0.16);
    border-radius: var(--gc-radius-sm, 2px);
    background: rgba(6, 12, 24, 0.85);
    color: rgba(220, 236, 255, 0.95);
    font: inherit;
    font-size: 0.82rem;
    font-weight: 600;
    letter-spacing: 0.04em;
    text-align: left;
    text-transform: uppercase;
    cursor: pointer;
  }

  .gc-bottom-buildings-menu-item:hover,
  .gc-bottom-buildings-menu-item:focus-visible{
    border-color: rgba(70, 229, 255, 0.45);
    background: rgba(70, 229, 255, 0.10);
    outline: none;
  }

  .gc-bottom-nav-item.is-menu-open{
    color: var(--gc-primary-2);
  }

  /* Drawer (More menu) ? class .is-open for smooth animation */
  .gc-nav-drawer{
    display: block;
    position: fixed;
    inset: 0;
    z-index: var(--gc-z-popover, 80);
    pointer-events: none;
    visibility: hidden;
  }

  .gc-nav-drawer.is-open{
    pointer-events: auto;
    visibility: visible;
  }

  .gc-nav-drawer-backdrop{
    position: fixed;
    inset: 0;
    background: rgba(2, 6, 14, 0.62);
    opacity: 0;
    transition: opacity 0.26s cubic-bezier(0.32, 0.72, 0, 1);
  }

  .gc-nav-drawer.is-open .gc-nav-drawer-backdrop{
    opacity: 1;
  }

  .gc-nav-drawer-panel{
    position: fixed;
    top: max(0px, var(--gc-safe-top));
    left: max(0px, var(--gc-safe-left));
    bottom: calc(var(--gc-bottom-nav-h) + var(--gc-safe-bottom));
    width: min(92vw, 380px);
    max-height: none;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    padding: 0;
    border-radius: 0 var(--gc-radius-sm) var(--gc-radius-sm) 0;
    background: rgba(7, 14, 32, 0.98);
    border: 1px solid var(--gc-panel-border);
    border-left: none;
    box-shadow: var(--gc-shadow-hard);
    transform: translateX(-104%);
    opacity: 0.92;
    transition:
      transform 0.28s cubic-bezier(0.32, 0.72, 0, 1),
      opacity 0.22s ease;
    will-change: transform, opacity;
  }

  .gc-nav-drawer.is-open .gc-nav-drawer-panel{
    transform: translateX(0);
    opacity: 1;
  }

  .gc-nav-drawer-head{
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex: 0 0 auto;
    padding: 14px 14px 10px;
    border-bottom: 1px solid rgba(120, 190, 255, 0.12);
  }

  .gc-nav-drawer-title{
    font-family: Orbitron, Inter, system-ui, sans-serif;
    font-weight: 800;
    color: var(--gc-primary);
    letter-spacing: 0.05em;
  }

  /* nav drawer tabs: visual owned by .gc-page-tabs */
  .gc-nav-drawer-tabs{ margin: 0 0 8px; }


  .gc-nav-drawer-body{
    flex: 1 1 auto;
    min-height: 0;
    overflow: hidden;
  }

  .gc-nav-drawer-panel-tab{
    display: none;
    height: 100%;
    overflow-y: auto;
    overscroll-behavior: contain;
    padding:
      10px 10px
      calc(12px + var(--gc-safe-bottom));
    -webkit-overflow-scrolling: touch;
  }

  .gc-nav-drawer-panel-tab.is-active{
    display: block;
  }

  .gc-nav-section--utility-mobile{
    display: grid;
    gap: 6px;
    margin-top: 8px;
    padding-top: 8px;
    border-top: 1px solid rgba(120, 190, 255, 0.12);
  }

  .gc-nav-section--utility-mobile .gc-nav-section-label{
    padding: 4px 10px 2px;
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: var(--gc-text-dim);
  }

  .gc-nav-section--utility-mobile .gc-nav-link{
    width: 100%;
    text-align: left;
    cursor: pointer;
    font: inherit;
  }

  .gc-sidebar-mobile-drawer{
    display: flex !important;
    flex-direction: column;
    gap: 6px;
    width: 100%;
    max-width: 100%;
    min-width: 0;
    position: static;
    top: auto;
    max-height: none;
    overflow: visible;
    padding: 0;
    border: none;
    background: transparent;
    box-shadow: none;
  }

  .gc-sidebar-mobile-drawer .gc-nav-link,
  .gc-sidebar-mobile-drawer .gc-nav-sub-link{
    min-height: var(--gc-touch-min);
    word-break: break-word;
    overflow-wrap: anywhere;
  }

  .gc-sidebar-mobile-drawer .gc-nav-link-label{
    min-width: 0;
  }

  .gc-nav-drawer-links{
    display: grid;
    gap: 8px;
  }

  .gc-nav-drawer-link{
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    min-height: var(--gc-touch-min);
    padding: 12px 14px;
    border-radius: var(--gc-radius-sm);
    border: 1px solid rgba(120, 190, 255, 0.16);
    background: rgba(5, 10, 22, 0.58);
    color: var(--gc-text-soft);
    font-weight: 700;
    font-size: 0.92rem;
  }

  .gc-nav-drawer-link.active{
    border-color: rgba(70, 229, 255, 0.55);
    color: var(--gc-primary-2);
    box-shadow: var(--gc-border-glow);
  }

  .gc-nav-drawer-group{
    display: flex;
    flex-direction: column;
    gap: 6px;
  }

  .gc-nav-drawer-group-label{
    padding: 4px 14px 0;
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: var(--gc-text-dim);
  }

  .gc-nav-drawer-sublink{
    margin-left: 8px;
    min-height: calc(var(--gc-touch-min) - 4px);
    padding-top: 10px;
    padding-bottom: 10px;
    font-size: 0.86rem;
    font-weight: 600;
  }

  body.gc-nav-drawer-open{ overflow: hidden; }

  /* Mobile: no floating special dock over gameplay ? utilities live in META drawer */
  .gc-special-root > .gc-special-bar{
    display: none !important;
  }

  .gc-special-root{
    left: 0;
    right: 0;
    bottom: auto;
    pointer-events: none;
  }

  .gc-special-root.is-open,
  .gc-special-root .gc-special-window:not([hidden]){
    pointer-events: auto;
  }

  .gc-special-window{
    left: max(10px, var(--gc-safe-left));
    right: max(10px, var(--gc-safe-right));
    width: auto;
    max-height: min(68dvh, 620px);
    bottom: calc(var(--gc-bottom-nav-h) + var(--gc-safe-bottom) + 12px);
  }

  .gc-special-window-layout{
    grid-template-columns: 1fr;
  }

  .gc-support-grid{
    grid-template-columns: 1fr;
  }
}

/* Narrow phones: 360?390px */
@media (max-width: 390px){
  .gc-header-pill-label{ display: none; }
  .gc-header-pill .res-sep{ display: none; }
  .gc-bottom-nav-label{ font-size: 0.58rem; }
  .res-value, .res-cap, #res-energy{ font-size: 0.74rem; }
}

@media (max-width: 768px) and (prefers-reduced-motion: reduce){
  .gc-nav-drawer-panel,
  .gc-nav-drawer-backdrop,
  .gc-bottom-nav-item{
    transition: none !important;
  }
}

/* =========================
   24) Desktop Enhancements (981px+)
   ========================= */
@media (min-width: 981px){
  .gc-bottom-nav,
  .gc-nav-drawer{ display: none !important; }

  .gc-body-ingame{ padding-bottom: 0; }

  .gc-sidebar-desktop{
    display: flex;
    position: sticky;
    top: var(--gc-sidebar-top, 136px);
    align-self: start;
    max-height: var(--gc-sidebar-max-height, calc(100dvh - var(--gc-sidebar-top, 136px) - var(--gc-sidebar-bottom-gap, 12px)));
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
    scrollbar-gutter: stable;
    scrollbar-width: thin;
    scrollbar-color: rgba(70, 229, 255, 0.35) rgba(4, 10, 22, 0.4);
  }

  .gc-sidebar--right.gc-sidebar-desktop{
    scrollbar-color: rgba(255, 176, 32, 0.35) rgba(4, 10, 22, 0.4);
  }

  .gc-sidebar-desktop::-webkit-scrollbar{
    width: 8px;
  }

  .gc-sidebar-desktop::-webkit-scrollbar-track{
    background: rgba(4, 10, 22, 0.45);
  }

  .gc-sidebar-desktop::-webkit-scrollbar-thumb{
    background: rgba(70, 229, 255, 0.32);
    border-radius: var(--gc-radius-pill);
  }

  .gc-layout{
    align-items: start;
  }

  .gc-header-cmd{
    position: sticky;
    top: 0;
    z-index: 80;
  }

  .gc-resource-sticky{
    position: static;
    padding-bottom: 0;
    background: none;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    box-shadow: none;
  }
}

/* =========================
   26) Command Console Header + Build Queue v1.7
   ========================= */

.gc-header-cmd{
  z-index: 80;
  overflow: visible;
}

.gc-header-cmd .gc-header-inner{
  display: flex;
  flex-direction: column;
  gap: 8px;
  overflow: visible;
  min-height: 0;
  height: auto;
}

.gc-header-row{
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.gc-header-row-top{
  position: relative;
  z-index: 30;
  justify-content: space-between;
  flex-wrap: wrap;
}

.gc-header-row-resources{
  position: relative;
  z-index: 1;
  width: 100%;
  min-height: 0;
  flex-wrap: wrap;
}

/* GC-642 / GC-643 ? queue row under resources (full width) */
.gc-header-row-queues{
  width: 100%;
  min-width: 0;
  align-items: stretch;
}

.gc-header-row-queues[hidden]{
  display: none !important;
}

.gc-header-queues-shell{
  width: 100%;
  min-width: 0;
  padding: 6px 10px 8px;
  border-color: rgba(127, 255, 217, 0.12);
}

.gc-header-queues-head{
  display: flex;
  align-items: center;
  min-width: 0;
  margin-bottom: 6px;
  padding-bottom: 4px;
  border-bottom: 1px solid rgba(127, 255, 217, 0.08);
}

.gc-header-queues-label{
  font-size: 0.62rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(127, 255, 217, 0.55);
  font-weight: 600;
}

.gc-header-queues-body{
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  gap: 8px;
  min-width: 0;
}

/* GC-642 / GC-643 ? universal global queue HUD (horizontal chips) */
.gc-global-queue-hud{
  display: flex;
  flex: 1 1 auto;
  min-width: 0;
  margin: 0;
  padding: 0;
  border: none;
  background: transparent;
  box-shadow: none;
  color: var(--gc-text-soft);
  overflow: visible;
}

.gc-global-queue-hud.is-empty,
.gc-global-queue-hud[hidden]{
  display: none !important;
}

.gc-global-queue-hud-body{
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  gap: 8px;
  flex: 1 1 auto;
  min-width: 0;
  width: 100%;
}

.gc-global-queue-hud-item{
  flex: 1 1 180px;
  min-width: min(100%, 180px);
  max-width: 100%;
}

.gc-global-queue-hud-chip{
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  height: 100%;
  padding: 8px 10px;
  border-radius: var(--gc-radius-sm);
  background: linear-gradient(180deg, rgba(8, 14, 28, 0.94), rgba(6, 10, 22, 0.82));
  border: 1px solid rgba(127, 255, 217, 0.14);
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, 0.28) inset,
    0 6px 14px rgba(0, 0, 0, 0.24);
  cursor: pointer;
  transition: border-color 0.12s ease, box-shadow 0.12s ease, background 0.12s ease;
}

.gc-global-queue-hud-chip:hover{
  border-color: rgba(70, 229, 255, 0.28);
  box-shadow: var(--gc-border-glow), 0 8px 18px rgba(0, 0, 0, 0.28);
}

.gc-global-queue-hud-chip.is-queued{
  opacity: 0.88;
}

.gc-global-queue-hud-chip-head{
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.gc-global-queue-hud-glyph{
  flex: 0 0 auto;
  font-size: 0.9rem;
  line-height: 1;
  opacity: 0.92;
}

.gc-global-queue-hud-chip-domain{
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.58rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(127, 255, 217, 0.62);
  font-weight: 700;
}

.gc-global-queue-hud-chip-title{
  font-size: 0.82rem;
  font-weight: 600;
  line-height: 1.25;
  color: var(--gc-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.gc-global-queue-hud-chip-subtitle{
  font-size: 0.68rem;
  line-height: 1.35;
  color: var(--gc-text-soft);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.gc-global-queue-hud-chip-foot{
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  min-width: 0;
  margin-top: auto;
  padding-top: 2px;
}

.gc-global-queue-hud-timer{
  flex: 1 1 auto;
  min-width: 0;
  font-size: 0.72rem;
  color: var(--gc-primary-2);
}

.gc-global-queue-hud-cancel{
  flex: 0 0 auto;
  min-width: 1.35rem;
  min-height: 1.35rem;
  padding: 0;
  line-height: 1;
  font-size: 0.72rem;
  color: rgba(255, 120, 120, 0.88);
  border-color: rgba(255, 120, 120, 0.22);
