}

.gc-header-cmd .resource-bar.resource-bar-cmd.resource-bar-with-planet-limit{
  grid-template-columns: repeat(5, minmax(0, 1fr));
}

.gc-header-cmd .hud-res-warn{
  display: block;
  margin-top: 2px;
  padding-left: 2px;
  font-size: 0.62rem;
