/* GC-547 ? idle / hidden tab: stop compositor-heavy effects */
body.gc-tab-hidden .gc-bg::after {
  opacity: 0;
}

body.gc-tab-hidden .gc-panel::before,
body.gc-tab-hidden .resource-bar::before {
  opacity: 0;
