  --pc-accent-rgb: 70, 229, 255;
}
.gc-player-card-shell[data-theme="cyan"] { --pc-accent: #46e5ff; --pc-accent-rgb: 70, 229, 255; }
.gc-player-card-shell[data-theme="violet"] { --pc-accent: #a878ff; --pc-accent-rgb: 168, 120, 255; }
