}
.gc-pc-cosmetic-chip-label {
  font-size: 0.72rem;
  letter-spacing: 0.02em;
  color: var(--gc-text-muted, #9aa8c4);
  max-width: 7em;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gc-pc-theme-swatch {
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
  border-radius: var(--gc-radius-sm, 2px);
  border: 1px solid rgba(255, 255, 255, 0.25);
