}
.gc-hud-select-native{
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
.gc-hud-select-trigger{
  width: 100%;
  justify-content: space-between;
  gap: 8px;
  padding: 7px 10px;
