}
.gc-cb-round-label {
  margin: 0 0 10px;
  color: var(--gc-text-dim);
  font-size: 0.8rem;
}
.gc-cb-lanes {
  position: relative;
  display: grid;
  grid-template-columns: repeat(var(--cb-lanes, 2), minmax(0, 1fr));
  gap: 10px;
}
.gc-cb-lane {
  border: 1px solid rgba(120, 160, 200, 0.25);
  background: rgba(0, 0, 0, 0.35);
  padding: 8px;
  min-width: 0;
  transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
.gc-cb-lane.is-winner {
  border-color: rgba(212, 175, 55, 0.85);
  box-shadow: 0 0 18px rgba(212, 175, 55, 0.2);
}
.gc-cb-lane-head {
