  margin-bottom: 8px;
  font-size: 0.85rem;
}
.gc-cb-lane-team {
  font-size: 0.7rem;
  color: #8eb7ff;
  letter-spacing: 0.06em;
}
.gc-cb-lane-rv {
  margin-left: auto;
  color: #f0d78c;
  font-weight: 700;
}
.gc-cb-lane-roller {
  position: relative;
  height: 72px;
  overflow: hidden;
  border: 1px solid rgba(70, 229, 255, 0.2);
  background: rgba(0, 8, 16, 0.65);
  margin-bottom: 8px;
}
.gc-cb-lane-roller::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 2px;
  background: rgba(212, 175, 55, 0.85);
  transform: translateX(-50%);
  z-index: 2;
  pointer-events: none;
}
.gc-cb-lane-strip {
  display: flex;
  gap: 6px;
  height: 100%;
  align-items: center;
  padding: 0 8px;
  will-change: transform;
}
.gc-cb-tile {
  flex: 0 0 56px;
  height: 56px;
  border: 1px solid rgba(120, 160, 200, 0.28);
  background: rgba(12, 18, 28, 0.9);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  font-size: 0.7rem;
}
.gc-cb-tile.is-winning {
  border-color: rgba(212, 175, 55, 0.9);
  box-shadow: 0 0 10px rgba(212, 175, 55, 0.35);
}
.gc-cb-tile-amt { font-size: 0.65rem; color: var(--gc-text-dim); }
.gc-cb-lane-drops {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
  max-height: 120px;
  overflow: auto;
  font-size: 0.72rem;
}
.gc-cb-lane-drops li {
  display: flex;
  justify-content: space-between;
  gap: 6px;
}
.gc-cb-theater-status {
  position: relative;
  margin: 12px 0 0;
  text-align: center;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #8eb7ff;
}
.gc-cb-theater-win {
  color: #f0d78c;
  font-weight: 700;
}
@media (max-width: 800px) {
  .gc-cb-lanes {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 520px) {
  .gc-cb-lanes {
    grid-template-columns: 1fr;
  }
}


.inventory-effect-text {
