}
.gc-queue-timekeeper-btn{
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.05rem;
  height: 1.05rem;
  padding: 0;
  margin: 0;
  border: 1px solid rgba(70, 229, 255, 0.28);
