  .gc-fleet-drawer-root.is-show-all .gc-fleet-drawer-panel,
  .gc-fleet-hud-root.is-show-all .gc-fleet-drawer-panel{
    display: flex !important;
    flex-direction: column;
    flex: 1 1 auto;
    min-height: 0;
    overflow: hidden;
    padding: 8px 10px 0;
