.login-rewards-day {
  --lr-edge: rgba(70, 84, 104, 0.9);
  position: relative;
  aspect-ratio: 1 / 1;
  width: 100%;
  margin: 0;
  padding: 0.3rem;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: flex-start;
  gap: 0.15rem;
  border: 1px solid var(--lr-edge);
  border-radius: var(--gc-radius-sm, 2px);
  background: linear-gradient(165deg, rgba(18, 26, 38, 0.96), rgba(6, 10, 16, 0.92));
  color: inherit;
  font: inherit;
  cursor: default;
  overflow: hidden;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
  transition: border-color 0.15s ease, box-shadow 0.15s ease, transform 0.12s ease;
}
.login-rewards-day:hover:not(:disabled),
.login-rewards-day:hover:disabled {
  transform: translateY(-1px);
  z-index: 2;
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35);
}
.login-rewards-day:disabled {
  cursor: default;
  opacity: 1;
}
.login-rewards-day--claimable {
  --lr-edge: rgba(94, 200, 255, 0.95);
  cursor: pointer;
  background:
    linear-gradient(155deg, rgba(94, 200, 255, 0.22), transparent 50%),
    linear-gradient(165deg, rgba(16, 34, 48, 0.98), rgba(6, 12, 20, 0.95));
  box-shadow:
    inset 0 0 0 1px rgba(94, 200, 255, 0.4),
    0 0 18px rgba(94, 200, 255, 0.22);
  animation: lr-claimable-pulse 2.2s ease-in-out infinite;
}
@keyframes lr-claimable-pulse {
  0%, 100% { box-shadow: inset 0 0 0 1px rgba(94, 200, 255, 0.35), 0 0 12px rgba(94, 200, 255, 0.14); }
  50% { box-shadow: inset 0 0 0 1px rgba(94, 200, 255, 0.7), 0 0 24px rgba(94, 200, 255, 0.34); }
}
@media (prefers-reduced-motion: reduce) {
  .login-rewards-day--claimable,
  .login-rewards-event-banner-pulse { animation: none; }
}
.login-rewards-day--claimed {
  border-color: rgba(70, 86, 98, 0.9);
  background:
