.login-rewards-day--locked .login-rewards-day-icon {
  opacity: 0.72;
}
.login-rewards-day--milestone {
  --lr-edge: rgba(255, 184, 77, 0.85);
  border-style: solid;
  box-shadow: inset 0 0 0 1px rgba(255, 184, 77, 0.22), 0 0 14px rgba(255, 184, 77, 0.12);
}
.login-rewards-day--event {
  box-shadow: inset 0 2px 0 #3dffc2, 0 0 12px rgba(61, 255, 194, 0.12);
}
.login-rewards-day--rarity-uncommon { --lr-edge: rgba(110, 207, 143, 0.55); }
.login-rewards-day--rarity-rare { --lr-edge: rgba(94, 176, 255, 0.55); }
