    inset 0 0 0 1px rgba(94, 200, 255, 0.35),
    0 0 0 1px rgba(94, 200, 255, 0.25);
}
.battle-pass-card--premium.is-selected,
.battle-pass-card--premium:focus-visible {
  border-color: rgba(212, 160, 23, 0.95);
