.battle-pass-page-btn {
  flex: 0 0 2.2rem;
  min-width: 2.2rem;
  padding: 0;
  font-size: 1.4rem;
  line-height: 1;
  align-self: stretch;
  border-radius: var(--gc-radius-sm, 2px);
}
.battle-pass-page-btn:disabled {
