}
.battle-pass-page-meta {
  grid-area: meta;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.65rem;
}
.battle-pass-page-label {
  font-size: 0.78rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--gc-text-muted, #8a93a3);
}
.battle-pass-preview {
  grid-area: preview;
  border: 1px solid var(--gc-border, #2a3344);
