.shop-packs-head {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  margin-top: 0.15rem;
}
.shop-packs-title {
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(180, 198, 220, 0.72);
  white-space: nowrap;
}

.shop-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(17.5rem, 1fr));
  gap: 0.9rem;
}

.shop-card {
  position: relative;
  display: flex;
  flex-direction: column;
  padding: 0;
  overflow: hidden;
  border: 1px solid rgba(70, 229, 255, 0.22);
  border-radius: var(--gc-radius-sm, 2px);
  background:
    linear-gradient(165deg, rgba(12, 22, 38, 0.92) 0%, rgba(4, 8, 16, 0.96) 55%, rgba(8, 14, 26, 0.94) 100%);
  box-shadow:
    inset 0 1px 0 rgba(120, 210, 255, 0.12),
    0 0 0 1px rgba(0, 0, 0, 0.35),
    0 10px 28px rgba(0, 0, 0, 0.28);
  transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
.shop-card:hover,
.shop-card:focus-within {
  border-color: rgba(70, 229, 255, 0.48);
  box-shadow:
    inset 0 1px 0 rgba(140, 230, 255, 0.18),
    0 0 0 1px rgba(70, 229, 255, 0.12),
    0 14px 34px rgba(0, 12, 28, 0.45),
    0 0 24px rgba(70, 229, 255, 0.08);
}
.shop-card.is-owned {
  opacity: 0.78;
  filter: saturate(0.82);
}
.shop-card-frame {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 3;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.03);
}
.shop-card-frame::before,
.shop-card-frame::after {
  content: "";
  position: absolute;
  width: 12px;
  height: 12px;
  border-color: rgba(70, 229, 255, 0.55);
  border-style: solid;
}
.shop-card-frame::before {
  top: 5px;
  left: 5px;
  border-width: 1px 0 0 1px;
}
.shop-card-frame::after {
  top: 5px;
  right: 5px;
  border-width: 1px 1px 0 0;
}
.shop-card::before {
  content: "";
  position: absolute;
  left: 5px;
  bottom: 5px;
  width: 12px;
  height: 12px;
  border-style: solid;
  border-color: rgba(70, 229, 255, 0.4);
  border-width: 0 0 1px 1px;
  z-index: 3;
  pointer-events: none;
}
.shop-card::after {
  content: "";
  position: absolute;
  right: 5px;
  bottom: 5px;
  width: 12px;
  height: 12px;
  border-style: solid;
  border-color: rgba(212, 175, 55, 0.45);
  border-width: 0 1px 1px 0;
  z-index: 3;
  pointer-events: none;
}

.shop-card--featured {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr);
  border-color: rgba(212, 175, 55, 0.38);
  background:
    linear-gradient(120deg, rgba(18, 24, 40, 0.96) 0%, rgba(8, 12, 22, 0.98) 48%, rgba(16, 20, 34, 0.95) 100%);
  box-shadow:
    inset 0 1px 0 rgba(232, 196, 90, 0.16),
    0 0 0 1px rgba(212, 175, 55, 0.12),
    0 16px 40px rgba(0, 0, 0, 0.38),
    0 0 36px rgba(212, 175, 55, 0.07);
}
.shop-card--featured:hover,
.shop-card--featured:focus-within {
  border-color: rgba(232, 196, 90, 0.58);
  box-shadow:
    inset 0 1px 0 rgba(232, 196, 90, 0.22),
    0 0 0 1px rgba(212, 175, 55, 0.2),
    0 18px 44px rgba(0, 8, 20, 0.5),
    0 0 40px rgba(212, 175, 55, 0.12);
}
.shop-card--featured .shop-card-art {
  aspect-ratio: auto;
  min-height: 15rem;
  height: 100%;
  border-bottom: none;
  border-right: 1px solid rgba(212, 175, 55, 0.22);
}
.shop-card--featured .shop-card-body {
  justify-content: center;
  gap: 1.1rem;
  padding: 1.15rem 1.25rem;
}
.shop-card--featured .shop-card-title {
  font-size: 1.35rem;
  letter-spacing: 0.03em;
}
.shop-card--featured .shop-card-price {
  font-size: 1.35rem;
  color: #e8c45a;
  text-shadow: 0 0 18px rgba(232, 196, 90, 0.25);
}

.shop-card-art {
  position: relative;
  margin: 0;
  aspect-ratio: 16 / 10;
  overflow: hidden;
  background: #05080f;
  border-bottom: 1px solid rgba(70, 229, 255, 0.16);
}
.shop-card-art::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background:
    radial-gradient(120% 80% at 50% 0%, rgba(70, 229, 255, 0.12), transparent 55%),
    linear-gradient(to top, rgba(3, 6, 12, 0.88) 0%, rgba(3, 6, 12, 0.2) 42%, transparent 70%);
}
.shop-card-art img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center;
  opacity: 0;
  transform: scale(1.04);
  transition: transform 0.55s ease, opacity 0.45s ease, filter 0.35s ease;
  animation: shop-art-in 0.55s ease forwards;
  filter: saturate(1.05) contrast(1.04);
}
.shop-card:hover .shop-card-art img,
.shop-card:focus-within .shop-card-art img {
  transform: scale(1.07);
  filter: saturate(1.12) contrast(1.06);
}
@keyframes shop-art-in {
  to {
    opacity: 1;
    transform: scale(1);
  }
}
@media (prefers-reduced-motion: reduce) {
  .shop-card,
  .shop-card-art img {
    transition: none;
  }
  .shop-card-art img {
    opacity: 1;
    transform: none;
    animation: none;
  }
  .shop-card:hover .shop-card-art img,
  .shop-card:focus-within .shop-card-art img {
    transform: none;
  }
}

.shop-card-kind,
.shop-card-featured-tag {
  position: absolute;
  z-index: 2;
  top: 0.55rem;
  padding: 0.18rem 0.45rem;
  border: 1px solid rgba(70, 229, 255, 0.35);
  border-radius: var(--gc-radius-sm, 2px);
  background: rgba(4, 10, 18, 0.78);
  font-size: 0.62rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(180, 230, 255, 0.92);
  backdrop-filter: blur(4px);
}
.shop-card-kind { left: 0.55rem; }
.shop-card-featured-tag {
  right: 0.55rem;
  left: auto;
  border-color: rgba(212, 175, 55, 0.5);
  color: #e8c45a;
  background: rgba(18, 14, 6, 0.82);
}

.shop-card-body {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 0.85rem;
  flex: 1;
  padding: 0.85rem 0.9rem 0.95rem;
}
.shop-card-title {
  margin: 0 0 0.4rem;
  font-size: 1.02rem;
  font-weight: 650;
  letter-spacing: 0.01em;
  color: #f2f6fb;
}
.shop-card-hint {
  margin: 0;
  line-height: 1.45;
  color: rgba(170, 188, 210, 0.88);
}
.shop-card-footer {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
  padding-top: 0.55rem;
  border-top: 1px solid rgba(70, 229, 255, 0.12);
}
.shop-card-price {
  margin: 0;
  font-size: 1.18rem;
  font-weight: 650;
  color: var(--gc-accent, #5ec8ff);
  text-shadow: 0 0 14px rgba(94, 200, 255, 0.2);
}
.shop-provider-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}
.shop-buy-btn.gc-btn-primary {
  box-shadow: 0 0 16px rgba(70, 229, 255, 0.12);
}
.shop-owned,
.shop-locked {
  display: inline-flex;
  align-items: center;
  min-height: 1.8rem;
  font-size: 0.72rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(160, 180, 200, 0.78);
}
.shop-policy-panel { margin-top: 0.75rem; }
.shop-return-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 0.85rem;
}

@media (max-width: 820px) {
  .shop-card--featured {
    grid-template-columns: 1fr;
  }
  .shop-card--featured .shop-card-art {
    min-height: 12rem;
    height: auto;
    aspect-ratio: 16 / 10;
    border-right: none;
    border-bottom: 1px solid rgba(212, 175, 55, 0.22);
  }
}
.battle-pass-premium-cta {
  margin-top: 0.65rem;
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
}
.battle-pass-premium-cta-art {
  width: 3.5rem;
  height: 3.5rem;
  object-fit: contain;
  flex: 0 0 auto;
  border: 1px solid rgba(212, 160, 23, 0.35);
  border-radius: var(--gc-radius-sm, 2px);
  background: rgba(0, 0, 0, 0.35);
  padding: 0.2rem;
}
.battle-pass-premium-cta-body {
  flex: 1;
  min-width: 0;
}
.battle-pass-premium-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
  margin-top: 0.45rem;
}

/* Public banned players board */
.banned-players-eyebrow {
  margin: 0 0 0.35rem;
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
