}
.banned-players-empty { margin: 0; color: var(--gc-text-muted, #8a93a3); }

/* ===== Genesis Story Ops (EPIC-25 / GC-2502) ===== */
/* ===== Story Ops — Center Focus Hero Layout (scoped) ===== */
.story-ops-page {
  --cc-vanguard: #e04545;
  --cc-forge: #e08a2a;
  --cc-archivist: #3ecfc9;
  --cc-admiral: #3a6fd9;
  --cc-envoy: #9b5de5;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  min-width: 0;
}
.story-ops-page .story-ops-eyebrow {
  margin: 0;
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--gc-text-muted, #8aa);
}
.story-ops-page .story-ops-layout {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  min-width: 0;
}

/* Hero transmission panel — hologram stage */
.story-ops-page .story-tx {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--gc-border, #2a3a44);
  background:
    radial-gradient(ellipse 70% 55% at 50% 28%, rgba(40, 90, 110, 0.16), transparent 70%),
    linear-gradient(180deg, rgba(6, 12, 18, 0.98), rgba(10, 20, 28, 0.94) 55%, rgba(8, 14, 20, 0.98));
  padding: 1.85rem 1.35rem 1.45rem;
  border-radius: var(--gc-radius-sm, 2px);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
}
.story-ops-page .story-tx__atmos {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
}
.story-ops-page .story-tx__nebula {
  position: absolute;
  inset: -10% -5% 20%;
  background:
    radial-gradient(ellipse 45% 35% at 30% 40%, rgba(90, 208, 230, 0.06), transparent 70%),
    radial-gradient(ellipse 40% 30% at 70% 35%, rgba(180, 140, 255, 0.05), transparent 70%);
  opacity: 0.9;
}
.story-ops-page .story-tx__stars {
  position: absolute;
  inset: 0;
  opacity: 0.55;
  background-image:
    radial-gradient(1px 1px at 12% 18%, rgba(220, 240, 255, 0.55), transparent),
    radial-gradient(1px 1px at 28% 62%, rgba(220, 240, 255, 0.35), transparent),
    radial-gradient(1px 1px at 44% 24%, rgba(220, 240, 255, 0.45), transparent),
    radial-gradient(1px 1px at 61% 71%, rgba(220, 240, 255, 0.3), transparent),
    radial-gradient(1px 1px at 76% 22%, rgba(220, 240, 255, 0.4), transparent),
    radial-gradient(1px 1px at 88% 48%, rgba(220, 240, 255, 0.28), transparent),
    radial-gradient(1.5px 1.5px at 53% 41%, rgba(90, 208, 230, 0.45), transparent);
}
.story-ops-page .story-tx__grid {
  position: absolute;
  inset: 0;
  opacity: 0.05;
  background-image:
    linear-gradient(rgba(90, 208, 230, 0.55) 1px, transparent 1px),
    linear-gradient(90deg, rgba(90, 208, 230, 0.55) 1px, transparent 1px);
  background-size: 36px 36px;
  mask-image: radial-gradient(ellipse 70% 60% at 50% 35%, #000 20%, transparent 75%);
}
.story-ops-page .story-tx__scan {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 0;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(80, 200, 220, 0.025) 3px
  );
  opacity: 0.65;
}
.story-ops-page .story-tx__hero {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.85rem;
  width: 100%;
  padding: 0.35rem 0 1.1rem;
}
.story-ops-page .story-tx__meta {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.28rem;
  text-align: center;
  max-width: 28rem;
}
.story-ops-page .story-tx__contact-label {
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-size: 1.45rem;
  line-height: 1.15;
  color: var(--gc-text, #e8f2f6);
  text-shadow: 0 0 18px color-mix(in srgb, var(--gc-accent, #5ad0e6) 25%, transparent);
}
.story-ops-page .story-tx__meta-rule {
  display: block;
  width: min(12rem, 55%);
  height: 1px;
  margin: 0.35rem 0 0.15rem;
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in srgb, var(--gc-accent, #5ad0e6) 55%, transparent),
    transparent
  );
}
.story-ops-page .story-tx__status {
  font-size: 0.78rem;
  color: var(--gc-accent, #5ad0e6);
  letter-spacing: 0.16em;
  text-transform: uppercase;
}
.story-ops-page .story-tx__chapter {
  font-size: 0.78rem;
  color: var(--gc-text-muted, #8aa);
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.story-ops-page .story-tx__rule {
  position: relative;
  z-index: 1;
  width: min(38rem, 92%);
  height: 1px;
  margin: 0.15rem 0 1rem;
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in srgb, var(--gc-border, #2a3a44) 90%, var(--gc-accent, #5ad0e6)),
    transparent
  );
}
.story-ops-page .story-tx__body {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 38rem;
  text-align: center;
  margin: 0 auto;
  padding-bottom: 0.15rem;
}
.story-ops-page .story-tx__title {
  margin: 0 0 0.45rem;
  font-size: 1.05rem;
  letter-spacing: 0.03em;
  font-weight: 600;
  color: var(--gc-text, #d7e6ec);
}
.story-ops-page .story-tx__text {
  margin: 0;
  line-height: 1.55;
  font-size: 0.92rem;
  color: var(--gc-text-muted, #b7c8d0);
