}
.story-ops-page .story-tx__actions:empty { display: none; }
.story-ops-page .story-tx__waiting { margin: 0; text-align: center; width: 100%; }

/* Story speaker — hologram Commander portrait (preferred) or contact orb fallback */
.story-ops-page .story-speaker,
.story-ops-page .story-orb {
  --story-orb-accent: #5ad0e6;
  --story-orb-glow: rgba(90, 208, 230, 0.55);
  --story-orb-size: 200px;
  --story-orb-core: 122px;
  --story-orb-eq-h: 36px;
  --story-speaker-w: 260px;
  --story-speaker-h: 340px;
  position: relative;
  width: var(--story-orb-size);
  height: var(--story-orb-size);
  flex-shrink: 0;
  display: grid;
  place-items: center;
}
.story-ops-page .story-speaker--commander {
  --story-orb-accent: var(--cc-theme, #5ad0e6);
  --story-orb-glow: color-mix(in srgb, var(--cc-theme, #5ad0e6) 55%, transparent);
  width: var(--story-speaker-w);
  height: var(--story-speaker-h);
  margin-bottom: -1.5rem;
}
.story-ops-page .story-speaker--vanguard { --cc-theme: var(--cc-vanguard); }
.story-ops-page .story-speaker--forge { --cc-theme: var(--cc-forge); }
.story-ops-page .story-speaker--archivist { --cc-theme: var(--cc-archivist); }
.story-ops-page .story-speaker--admiral { --cc-theme: var(--cc-admiral); }
.story-ops-page .story-speaker--envoy { --cc-theme: var(--cc-envoy); }
.story-ops-page .story-orb--androgyn {
  --story-orb-accent: #c4a0ff;
  --story-orb-glow: rgba(180, 140, 255, 0.55);
}

/* Hologram field behind portrait */
.story-ops-page .story-holo {
  position: absolute;
  inset: -18% -22%;
  z-index: 0;
  pointer-events: none;
}
.story-ops-page .story-holo__orbit {
  position: absolute;
  left: 50%;
  top: 48%;
  border: 1px solid color-mix(in srgb, var(--story-orb-accent) 28%, transparent);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  opacity: 0.45;
}
.story-ops-page .story-holo__orbit--a {
  width: 88%;
  height: 62%;
  animation: story-holo-spin 28s linear infinite;
}
.story-ops-page .story-holo__orbit--b {
  width: 108%;
  height: 78%;
  border-style: dashed;
  opacity: 0.28;
  animation: story-holo-spin 42s linear infinite reverse;
}
.story-ops-page .story-holo__orbit--c {
  width: 68%;
  height: 48%;
  opacity: 0.35;
  animation: story-holo-spin 18s linear infinite;
}
.story-ops-page .story-holo__pulse {
  position: absolute;
  left: 50%;
  top: 42%;
  width: 55%;
  height: 40%;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--story-orb-accent) 40%, transparent);
  box-shadow: 0 0 18px color-mix(in srgb, var(--story-orb-glow) 25%, transparent);
  opacity: 0.25;
  animation: story-holo-breathe 3.6s ease-in-out infinite;
}
.story-ops-page .story-speaker.is-speaking .story-holo__pulse {
  opacity: 0.7;
  animation: story-holo-speak-pulse 1.1s ease-in-out infinite;
  box-shadow: 0 0 28px color-mix(in srgb, var(--story-orb-glow) 55%, transparent);
}
.story-ops-page .story-holo__marker {
  position: absolute;
  width: 5px;
  height: 5px;
  border: 1px solid color-mix(in srgb, var(--story-orb-accent) 70%, transparent);
  background: color-mix(in srgb, var(--story-orb-accent) 35%, transparent);
  opacity: 0.55;
}
.story-ops-page .story-holo__marker--1 { left: 8%; top: 28%; }
.story-ops-page .story-holo__marker--2 { right: 10%; top: 22%; }
.story-ops-page .story-holo__marker--3 { left: 14%; bottom: 30%; }
.story-ops-page .story-holo__marker--4 { right: 12%; bottom: 26%; }
.story-ops-page .story-holo__particles {
  position: absolute;
  inset: 10% 18% 18%;
  background-image:
    radial-gradient(1px 1px at 20% 80%, color-mix(in srgb, var(--story-orb-accent) 70%, transparent), transparent),
    radial-gradient(1px 1px at 55% 70%, color-mix(in srgb, var(--story-orb-accent) 55%, transparent), transparent),
    radial-gradient(1px 1px at 78% 85%, color-mix(in srgb, var(--story-orb-accent) 45%, transparent), transparent),
    radial-gradient(1.5px 1.5px at 40% 60%, color-mix(in srgb, var(--story-orb-accent) 40%, transparent), transparent);
  animation: story-holo-drift 7s ease-in-out infinite;
  opacity: 0.55;
}
.story-ops-page .story-speaker--orb .story-holo { display: none; }

.story-ops-page .story-speaker__frame {
  position: relative;
  z-index: 2;
  width: 100%;
  height: 100%;
  border: none;
  border-radius: var(--gc-radius-sm, 2px);
  overflow: hidden;
  background: transparent;
  -webkit-mask-image: linear-gradient(180deg, #000 0%, #000 52%, rgba(0, 0, 0, 0.55) 78%, transparent 100%);
  mask-image: linear-gradient(180deg, #000 0%, #000 52%, rgba(0, 0, 0, 0.55) 78%, transparent 100%);
  box-shadow:
    0 0 36px color-mix(in srgb, var(--story-orb-glow) 40%, transparent),
    0 0 70px color-mix(in srgb, var(--story-orb-glow) 16%, transparent);
  animation: story-holo-flicker 6.5s ease-in-out infinite;
}
.story-ops-page .story-speaker__portrait {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center top;
