.fleet-troops-panel {
  margin-top: var(--gc-space-3, 12px);
  border-radius: var(--gc-radius-sm, 2px);
}
.barracks-troops-grid,
.fleet-troops-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 8px;
}
.barracks-troop-card,
.fleet-troop-card {
  border: 1px solid var(--gc-border, #2a3340);
